///////// 5. 일반/업무 함수 영역 /////////
// 조회조건이 담길 배열

/**
 * @method
 * @name initDs
 * @description 데이터셋 초기화.
 * @returns {void}
 * @hidden N
 */
scwin.initDs = function() {
    dts_RetiPayAlwncDtl1.removeAll();
    dts_RetiPayAlwncDtl2.removeAll();
};

/**
 * @method
 * @name chkValid
 * @description 조회조건 유효성 체크
 * @returns {void}
 * @hidden N
 */
scwin.chkValid = function() {
    return true;
};

/**
 * @method
 * @name search
 * @description 퇴직급여충당금 상세 조회
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function() {
    // 데이터셋 초기화
    scwin.initDs();

    // 조회조건 필수 체크.
    if (!scwin.chkValid()) {
        return;
    }

    // 퇴직급여충당금 상단 그리드 조회
    await scwin.retiPayAlwncDtl1();
};
